            position: "fixed",
            right: 20,
            bottom: 20,
            width: SIZE,
            height: SIZE,
            borderRadius: "50%",
            border: "1px solid rgba(120,130,200,.30)",
            background: "var(--soft, rgba(120,130,200,.10))",
            color: "var(--ink2, #4a5170)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            cursor: busy ? "progress" : "pointer",
            padding: 0,
            zIndex: 30,
